1: /* ================= main.js — boot, cameras, audio, game loop ========== */
2: (function () {
3:   const RC = window.RC, THREE = window.THREE, UI = RC.ui;
4:   if (!window.THREE) { UI.err('three.js failed to load'); return; }
5: 
6:   /* ------------------------------------------------ renderer & scene */
7:   const canvas = document.getElementById('c');
8:   const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
9:   renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
10:   renderer.shadowMap.enabled = true;
11:   renderer.shadowMap.type = THREE.PCFSoftShadowMap;
12:   renderer.outputEncoding = THREE.sRGBEncoding;
13:   renderer.toneMapping = THREE.ACESFilmicToneMapping;
14:   renderer.toneMappingExposure = 1.15;
15: 
16:   const scene = new THREE.Scene();
17:   scene.background = new THREE.Color(0x050507);
18:   const camera = new THREE.PerspectiveCamera(52, 1, .1, 120);
19:   camera.position.set(0, 2.4, 6);
20:   function resize() {
21:     const w = innerWidth, h = innerHeight;
22:     renderer.setSize(w, h, false);
23:     camera.aspect = w / h;
24:     camera.updateProjectionMatrix();
25:   }
26:   addEventListener('resize', resize); resize();
27: 
28:   /* ------------------------------------------------ world */
29:   const W = RC.buildWorld(scene);
30:   window.__worldRef = W;
31: 
32:   /* jury rats: built & seated behind desk */
33:   const juryRats = RC.JURY.map((juror, i) => {
34:     const spec = RC.randomRatSpec();
35:     spec.hairStyle = i === 0 ? 'mohawk' : i === 1 ? 'pigtails' : 'bald';
36:     spec.scale = .92;
37:     const chr = RC.buildRat(spec);
38:     RC.buildRat.seated(chr);
39:     const seat = W.jurySeats[i];
40:     chr.group.position.set(seat.x, seat.y, seat.z);
41:     chr.group.rotation.y = Math.PI; // face the runway (-z)
42:     scene.add(chr.group);
43:     return { juror, chr };
44:   });
