160:   /* ------------------------------------------------ contestants */
161:   function makeContestant(isPlayer, name) {
162:     const spec = RC.randomRatSpec();
163:     spec.hairStyle = RC.pick(['messy', 'mohawk', 'scrags', 'pigtails', 'bald']);
164:     const chr = RC.buildRat(spec);
165:     scene.add(chr.group);
166:     return {
167:       isPlayer, name, chr, score: 0, roundScore: 0, outfitItems: [],
168:       ai: null,
169:     };
170:   }
