172:   /* spots behind the start line */
173:   function lineupSpot(i) { return { x: -2.4 + i * 1.2, y: .12, z: -14.6 }; }
174:   let contestants = [];
175:   function newGame() {
176:     contestants.forEach(c => { scene.remove(c.chr.group); RC.clearOutfit(c.chr); });
177:     contestants = [];
178:     const aiNames = RC.shuffled(RC.RAT_NAMES).slice(0, 4);
179:     const player = makeContestant(true, RC.PLAYER_NAMES[RC.ri(0, RC.PLAYER_NAMES.length - 1)]);
180:     contestants.push(player);
181:     aiNames.forEach(n => contestants.push(makeContestant(false, n)));
182:     contestants.forEach((c, i) => {
183:       const s = lineupSpot(i);
184:       c.chr.group.position.set(s.x, s.y, s.z);
185:       c.chr.group.rotation.y = 0;
186:       c.chr.anim.mode = 'idle';
187:     });
188:     return player;
189:   }
