191:   /* ------------------------------------------------ lighting fx */
192:   function spotlightOn(chr) {
193:     if (!chr || !chr.group) { UI.err('spotlightOn bad arg ' + JSON.stringify(chr && Object.keys(chr))); return; }
194:     const p = chr.group.position;
195:     W.keyTarget.position.set(p.x, 1.2, p.z);
196:     W.key.position.set(p.x, 10.5, p.z + 4.5);
197:   }
198:   function flashBurst(atPos, big) {
199:     UI.flash();
200:     Audio.shutter();
201:     const l = new THREE.PointLight(0xffffff, big ? 9 : 5.5, 12);
202:     l.position.copy(atPos); l.position.y += .4;
203:     scene.add(l);
204:     RC.Tweens.add({
205:       dur: .38, ease: x => x,
206:       onUpdate: k => { l.intensity = (big ? 9 : 5.5) * (1 - k); },
207:       resolve: () => scene.remove(l),
208:     });
209:     Cam.kick(.22);
210:     /* the crowd goes feral with phone flashes */
211:     for (let i = 0; i < (big ? 10 : 5); i++) {
212:       RC.wait(RC.rand(.05, .8)).then(() => {
213:         if (!W.crowd.length) return;
214:         const c = RC.pick(W.crowd);
215:         const fl = new THREE.PointLight(0xeef4ff, 3, 6);
216:         fl.position.copy(c.position); fl.position.y += 1.1;
217:         scene.add(fl);
218:         RC.Tweens.add({
219:           dur: .22, ease: x => x,
220:           onUpdate: k => fl.intensity = 3 * (1 - k),
221:           resolve: () => scene.remove(fl),
222:         });
223:       });
224:     }
225:   }
