227:   /* crown + confetti for the finale */
228:   function dressCrown(chr) {
229:     const g = new THREE.Group();
230:     const gold = M.chip(0xd8a832); 
231:     const band = new THREE.Mesh(new THREE.TorusGeometry(.15, .022, 8, 16), gold);
232:     band.rotation.x = Math.PI / 2; g.add(band);
233:     for (let i = 0; i < 8; i++) {
234:       const a = i / 8 * Math.PI * 2;
235:       const sp = new THREE.Mesh(new THREE.ConeGeometry(.012, .05, 6), gold);
236:       sp.position.set(Math.cos(a) * .15, .03, Math.sin(a) * .15);
237:       g.add(sp);
238:     }
239:     const gem = new THREE.Mesh(new THREE.SphereGeometry(.018, 8, 6), M.emissive(0x9dff2a, 3));
240:     gem.position.set(0, .04, .15); g.add(gem);
241:     g.position.set(chr.bones.head.position.x, 1.2, 0);
242:     g.position.set(0, 1.6, 0);
243:     chr.anchors.head.add(g);
244:     g.position.set(0, 2.2, 0);
245:     RC.Tweens.add({
246:       dur: 1.3, onUpdate: k => {
247:         g.position.y = RC.lerp(2.2, .28, k);
248:         g.rotation.z = (1 - k) * 1.2;
249:       },
250:     }).then(() => { Audio.thud(); Cam.kick(.3); });
251:     /* flies + raw glitz rain of can tab confetti */
252:     for (let i = 0; i < 40; i++) {
253:       const conf = new THREE.Mesh(
254:         new THREE.BoxGeometry(.015, .004, .03),
255:         RC.pick([M.chip(0x9dff2a), M.chip(0xff2a6d), M.chip(0xe8dcc0), M.chip(0x2af5ff)])
256:       );
257:       conf.position.set(chr.group.position.x + RC.rand(-2, 2), RC.rand(5, 9), chr.group.position.z + RC.rand(-2, 2));
258:       scene.add(conf);
259:       const spin = RC.rand(2, 7), sway = RC.rand(1, 3);
260:       RC.Tweens.add({
261:         dur: RC.rand(2.5, 5.5), ease: x => x,
262:         onUpdate: (k, dtless) => {
263:           conf.position.y -= .016;
264:           conf.position.x += Math.sin(k * sway * 6) * .004;
265:           conf.rotation.x += spin * .016; conf.rotation.z += spin * .011;
266:         },
267:         resolve: () => scene.remove(conf),
268:       });
269:     }
270:   }
