272:   /* ------------------------------------------------ the game */
273:   let player = null;
274:   let busy = true;
275:   const ROUNDS = 5;
276: 
277:   const btnSendDummy = document.getElementById('btnSend');
278:   document.getElementById('btnRestyle').onclick = () => {
279:     Audio.boot(); Audio.click();
280:     player = player || makeContestant(true, RC.PLAYER_NAMES[RC.ri(0, RC.PLAYER_NAMES.length - 1)]);
281:     scene.remove(player.chr.group);
282:     player.chr = RC.buildRat(RC.randomRatSpec());
283:     const s = lineupSpot(0);
284:     player.chr.group.position.set(Cam.mode === 'title' ? 0 : s.x, Cam.mode === 'title' ? .12 : s.y, Cam.mode === 'title' ? -2 : s.z);
285:     scene.add(player.chr.group);
286:     player.isPlayer = true;
287:     updatePlayerName();
288:     Audio.thud();
289:   };
