325:   /* ---- walker positioning helpers ---- */
326:   const RUNWAY_Z0 = -12.4;   // start line (backstage door)
327:   const POSE_Z = 8.2;        // pose spot in front of jury
328:   const OFF_X = 4.4, OFF_Z = 10.6;
329: 
330:   async function walkIn(chr, from, to, dur) {
331:     RC.resetRatPose(chr);
332:     chr.anim.mode = 'walk'; chr.anim.speed = .75;
333:     chr.group.position.set(from.x, from.y, from.z);
334:     const fx = from.x, fz = from.z;
335:     await RC.Tweens.add({
336:       dur,
337:       onUpdate: k => { chr.group.position.set(fx, from.y, RC.lerp(fz, to.z, k)); },
338:     });
339:   }
340:   async function walkOut(chr, target, dur) {
341:     RC.resetRatPose(chr);
342:     chr.anim.mode = 'walk'; chr.anim.speed = .9;
343:     const fx = chr.group.position.x, fz = chr.group.position.z;
344:     await RC.Tweens.add({
345:       dur,
346:       onUpdate: k => { chr.group.position.set(RC.lerp(fx, target.x, k), target.y, RC.lerp(fz, target.z, k)); },
347:     });
348:   }
349:   function parkContestants(list) {
350:     list.forEach((c, i) => {
351:       const s = lineupSpot(i);
352:       c.chr.group.position.set(s.x, s.y, s.z);
353:       RC.resetRatPose(c.chr);
354:       c.chr.anim.mode = 'idle';
355:       c.chr.anim.speed = 0;
356:       c.chr.group.visible = true;
357:     });
358:   }
359: 
360:   async function dressPhase(cats, playerC) {
361:     const pc = playerC.chr;
362:     RC.resetRatPose(pc);
363:     pc.group.rotation.y = 0;
364:     pc.group.position.set(0, .12, -2.5);
365:     pc.group.visible = true;
366:     pc.anim.mode = 'idle';
367:     spotlightOn(playerC);
368:     Cam.set('dress', playerC.chr);
369:     UI.outfitTags([]);
370:     return new Promise(res => {
371:       UI.openDresser(cats, (catId, itemOrRandom) => {
372:         if (!catId && itemOrRandom === true) {
373:           cats.forEach(c => RC.wear(pc, c.id, UI.picks[c.id]));
374:         } else if (catId) {
375:           RC.wear(pc, catId, itemOrRandom);
376:           UI.outfitTags(Object.values(UI.picks).filter(Boolean));
377:         }
378:       }, picks => {
379:         UI.closeDresser();
380:         cats.forEach(c => RC.wear(pc, c.id, picks[c.id]));
381:         UI.outfitTags(Object.values(picks));
382:         res(picks);
383:       });
384:     });
385:   }
