```
4. confirmCharacter(savedCfg):
```
function confirmCharacter(cfgSaved) {
  Audio.boot(); Audio.stinger();
  W.root.visible = true;
  juryRats.forEach(j => j.chr.group.visible = true);
  /* rebuild the player from the saved configuration */
  RC.playerUberSpec = RC.specFromConfig(cfgSaved);
  RC.playerName = cfgSaved.name || 'UNNAMED FREAK';
  applyPlayerCharacter();
  runMatch();
}
```
applyPlayerCharacter:
```
function applyPlayerCharacter() {
  if (!RC.playerUberSpec) return;
  if (player) {
    const old = player.chr;
    RC.clearOutfit(old); scene.remove(old.group);
